12	uses(IsolatedAccountTestCase::class);
13	
14	// QUAL-003's situation (invariant:NAKED_BESIDE_WALLED, aspect:shipyard). The cohort read found accounts
15	// with planets at zero defence while a sibling held a real wall: the whole wall was raised on the planet
16	// with the most to lose and the bare siblings were never reached. One login has to give the bare planet
17	// the wall order the account already holds elsewhere, in the host's own yard.
18	test('a login gives the bare sibling the wall the account already holds elsewhere', function (): void {
19	    $situation = Situation::of($this)
20	        ->levelEveryPlanet('robot_factory', 2)
21	        ->levelEveryPlanet('shipyard', 4)
22	        ->defence('rocket_launcher', 20)
23	        ->stockEveryPlanet(20_000_000, 10_000_000, 5_000_000)
24	        ->session();
25	
26	    $bare = Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)
27	        ->whereKeyNot($this->currentPlanetId)->value('id');
28	    $planet = app(PlanetServiceFactory::class)->make((int) $bare, true);
29	
30	    $situation->expectWork(AiWorkKind::QueueUnits);
31	
32	    // A short build may already be complete by the time the session's own clock has advanced to every
33	    // intent, so the wall counts whether it is standing or still paid for in the yard.
34	    expect(app(DefenseNeedEvaluator::class)->standingUnits($planet))->toBeGreaterThan(0, 'expected the wall on the bare sibling; ' . $situation->account());
35	});
36	
37	// The bound on the other side: a planet that already holds a wall is not the account's next wall order,
38	// so one login serves the bare sibling instead of stacking yet another batch on the walled planet.
39	test('a login does not spend its wall order on the planet that already holds one', function (): void {
40	    $situation = Situation::of($this)
41	        ->levelEveryPlanet('robot_factory', 2)
42	        ->levelEveryPlanet('shipyard', 4)
43	        ->defence('rocket_launcher', 20)
44	        ->stockEveryPlanet(20_000_000, 10_000_000, 5_000_000)
45	        ->session();
46	
47	    $home = app(PlanetServiceFactory::class)->make($this->currentPlanetId, true);
48	    $situation->expectWork(AiWorkKind::QueueUnits);
49	
50	    expect(app(DefenseNeedEvaluator::class)->standingUnits($home))->toBe(20, 'expected the walled planet untouched while its sibling is bare; ' . $situation->account());
51	});

