 14	// invariant:NAKED_BESIDE_WALLED (aspect:shipyard): the cohort read found a planet at zero defence beside a
 15	// sibling holding a wall, because the walled sibling kept taking the account's one wall order per login.
 16	// A walled planet whose production and standing ships outrun its wall still asks for more, and while a
 17	// sibling stands bare that order is withheld: the login's wall effort goes to the bare planet instead.
 18	test('a walled homeworld takes no further wall while its colony is still bare', function (): void {
 19	    povertyProfile($this->currentUserId);
 20	
 21	    $home = $this->planetService;
 22	    povertyWalledHome($home);
 23	
 24	    // A colony that mines nothing and whose yard cannot build a wall yet: the naked planet the cohort
 25	    // read found beside the account's wall. Nothing here can be served, so the walled homeworld is the
 26	    // only planet that could take the order -- and it must not.
 27	    povertyBareColony($this->secondPlanetService);
 28	
 29	    $plan = app(QueueableUnitPlanner::class)->plan($this->currentUserId);
 30	
 31	    expect($plan?->reason ?? '')->not->toContain('role:defense')
 32	        ->and($plan?->planetId)->not->toBe($home->getPlanetId());
 33	});
