 35	// The bound on the other side: the same account, with the bare colony able to pay for and build its own
 36	// wall, spends the order on the colony and still leaves the sibling that already stands a wall alone.
 37	test('the bare colony beside the walled homeworld takes the wall once it can pay for it', function (): void {
 38	    povertyProfile($this->currentUserId);
 39	
 40	    $home = $this->planetService;
 41	    povertyWalledHome($home);
 42	
 43	    $colony = povertyBareColony($this->secondPlanetService);
 44	    $colony->setObjectLevel(ObjectService::getObjectByMachineName('robot_factory')->id, 2, true);
 45	    $colony->setObjectLevel(ObjectService::getObjectByMachineName('shipyard')->id, 4, true);
 46	    $colony->updateResourceProductionStats();
 47	    $colony->updateResourceStorageStats();
 48	    $colony->addResources(new Resources(50_000_000, 50_000_000, 50_000_000));
 49	
 50	    $plan = app(QueueableUnitPlanner::class)->plan($this->currentUserId);
 51	
 52	    expect($plan)->not->toBeNull()
 53	        ->and($plan->reason)->toContain('role:defense:standing')
