 57	function povertyProfile(int $playerId): AiProfile
 58	{
 59	    return AiProfile::create([
 60	        'player_id' => $playerId,
 61	        'archetype' => AiArchetype::Miner,
 62	        'skill_band' => AiSkillBand::Standard,
 63	        'random_seed' => 51_000 + $playerId,
 64	        'enabled' => true,
 65	    ]);
 66	}
