 68	/**
 69	 * A homeworld that already stands a wall and whose economy and fleet are worth far more than it: the
 70	 * exposure the evaluator sizes from (PERS-004) is what makes it ask for further wall, so withholding the
 71	 * order is the rule under test rather than a need the planet never had.
 72	 */
 73	function povertyWalledHome(PlanetService $home): void
 74	{
 75	    foreach (['robot_factory' => 2, 'shipyard' => 4, 'solar_plant' => 30, 'metal_mine' => 20, 'crystal_mine' => 18, 'deuterium_synthesizer' => 12] as $machineName => $level) {
 76	        $home->setObjectLevel(ObjectService::getObjectByMachineName($machineName)->id, $level, true);
 77	    }
 78	
 79	    $home->updateResourceProductionStats();
 80	    $home->updateResourceStorageStats();
 81	    $home->addUnit('rocket_launcher', 2);
 82	    povertyOpeningFleet($home);
 83	    $home->addResources(new Resources(50_000_000, 50_000_000, 50_000_000));
 84	}
 85	
 86	/**
 87	 * A colony that mines nothing, holds no defence and whose yard cannot build any: the planet the cohort
 88	 * read found naked beside a walled sibling. Its own yard and stock decide whether it can be served, so a
 89	 * story plants what it means it to have afterwards.
 90	 */
 91	function povertyBareColony(?PlanetService $colony): PlanetService
 92	{
 93	    $colony = $colony ?? throw new LogicException('the account must own a second planet for this story.');
 94	
 95	    foreach (['robot_factory', 'shipyard', 'metal_mine', 'crystal_mine', 'deuterium_synthesizer'] as $machineName) {
 96	        $colony->setObjectLevel(ObjectService::getObjectByMachineName($machineName)->id, 0, true);
 97	    }
 98	
 99	    $colony->updateResourceProductionStats();
100	    $colony->updateResourceStorageStats();
101	
102	    return $colony;
103	}
