12	// the bare colony's chain is the usual one -- no facility is hoisted for a sibling that holds nothing.
13	test('a bare colony with no wall anywhere in the account is chained as usual', function (): void {
14	    $colony = $this->secondPlanetService ?? throw new LogicException('the account must own a colony for this story.');
15	    $colony->addResources(new Resources(5_000_000_000, 5_000_000_000, 5_000_000_000));
16	
17	    // A movable hull but no defence at all: the account is past nothing.
18	    $this->planetAddUnit('small_cargo', 1);
19	
20	    $wanted = walledSiblingWallFacilities();
21	    $chain = walledSiblingChainNames($colony);
22	
23	    expect($wanted)->not->toBeEmpty('the host must offer a defence unit to chain for')
