27	// And a planet that already holds the wall is never handed the wall's own facility: the rule moves
28	// only the naked planet.
29	test('a walled planet is not chained to the facility its own wall already needed', function (): void {
30	    $this->planetAddUnit('light_laser', 1);
31	    $this->planetAddUnit('small_cargo', 1);
32	
33	    $wanted = walledSiblingWallFacilities();
34	    $chain = walledSiblingChainNames($this->planetService);
35	
36	    expect(array_intersect($wanted, $chain))->toBeEmpty('a planet holding a wall must not be chained to the wall facility, but its chain is: [' . implode(', ', $chain) . ']');
