39	/** @return list<string> the machine names of the facilities the host's cheapest defence unit needs */
40	function walledSiblingWallFacilities(): array
41	{
42	    $cheapest = null;
43	    $cheapestPrice = INF;
44	
45	    foreach (ObjectService::getDefenseObjects() as $defence) {
46	        $price = ObjectService::getObjectRawPrice($defence->machine_name)->sum();
47	        if ($price <= 0 || $price >= $cheapestPrice) {
48	            continue;
49	        }
50	
51	        $cheapest = $defence;
52	        $cheapestPrice = $price;
53	    }
54	
55	    return $cheapest === null ? [] : array_keys(ObjectService::getRecursiveRequirements($cheapest->machine_name));
56	}
57	
58	/** @return list<string> the machine names of every step the planet's own chain proposes */
59	function walledSiblingChainNames(PlanetService $planet): array
60	{
61	    return array_map(
62	        static fn ($candidate): string => explode(':', $candidate->reason, 2)[1] ?? '',
63	        app(FacilityChain::class)->pending($planet),
64	    );
65	}

